tool_input.command:
cd src/data && node -e "
const fs=require('fs');let s=fs.readFileSync('products.ts','utf8');
const facts={'canvas-field-tote':'18 oz canvas','waxed-day-pack':'22 litre pack','weekender-duffel':'45 litre duffel','merino-crew-sweater':'100% merino','heavyweight-pocket-tee':'240 gsm jersey','cotton-chore-coat':'Cotton twill','enamel-camp-mug':'350 ml steel','cast-iron-skillet':'Pre-seasoned iron','linen-tea-towels':'100% linen','leather-key-ring':'Veg-tanned leather','ribbed-wool-beanie':'Wool blend'};
for(const [slug,fact] of Object.entries(facts)){s=s.replace(\"slug: '\"+slug+\"',\",\"slug: '\"+slug+\"',\n    spec: '\"+fact+\"',\");}
s=s.replace('  name: string;\n  category','  name: string;\n  /** One fact for the spec plate caption, at most 18 characters. */\n  spec: string;\n  category');
fs.writeFileSync('products.ts',s);" && grep -c "spec:" products.ts
